// The high-risk (permission, template) pairs of runtime roles, generated by code from the
// release compiled from src and pinned here: a new permission or template must be classified.
import assert from 'node:assert/strict';
import { test } from 'node:test';
import type { RoleGrantSpec } from '../dist/authorization/helpers/role-grant.helper.js';
import {
  createProductAuthorizationCore,
  createProductRelease,
} from '../dist/authorization/product.manifest.js';
import {
  SELF_APPROVAL_PERMISSIONS,
  hasSelfApproval,
  highRiskGrantPairs,
} from '../dist/modules/role/role-risk.helper.js';

const declarations = createProductRelease(createProductAuthorizationCore()).declarations;

const grant = (permission: string, template = 'x'): RoleGrantSpec => ({
  permission,
  template: { key: template, version: 1 },
});

/** Every (permission, template) a runtime role may pick: same resource, no parameters, not `document`. */
const selectable = Object.entries(declarations.resources).flatMap(([resource, declared]) =>
  resource === 'document'
    ? []
    : Object.keys(declared.actions).flatMap((action) =>
        Object.values(declarations.templates)
          .filter((t) => t.resource === resource && Object.keys(t.parameters).length === 0)
          .map((t) => `${resource}.${action} ${t.key}`),
      ),
);

const pinnedHighRiskPairs = [
  'account.provision allAccounts',
  'account.reactivate allAccounts',
  'account.read allAccounts',
  'account.readPermissions allAccounts',
  'account.suspend allAccounts',
  'employee.adjustAttendance ledEmployees',
  'employee.adjustAttendance selfEmployee',
  'employee.adjustLeaveBalance ledEmployees',
  'employee.adjustLeaveBalance selfEmployee',
  'employee.adjustLeaveRate ledEmployees',
  'employee.adjustLeaveRate selfEmployee',
  'employee.linkAccount allEmployees',
  'employee.linkAccount ledEmployees',
  'employee.linkAccount selfEmployee',
  'employee.submitRequest allEmployees',
  'employee.submitRequest ledEmployees',
  'employee.update allEmployees',
  'employee.update ledEmployees',
  'team.assign allTeams',
  'team.assign ledTeams',
  'team.assign memberTeams',
  'workRequest.cancel allRequests',
  'workRequest.cancel decidedRequests',
  'workRequest.cancel finalQueue',
  'workRequest.cancel leadRejectedLeadRequests',
  'workRequest.cancel ledRequests',
  'workRequest.cancel ownRequests',
  'workRequest.cancelApproved allRequests',
  'workRequest.cancelApproved decidedRequests',
  'workRequest.cancelApproved finalQueue',
  'workRequest.cancelApproved leadRejectedLeadRequests',
  'workRequest.cancelApproved ledRequests',
  'workRequest.cancelApproved ownRequests',
  'workRequest.decideFinal allRequests',
  'workRequest.decideFinal decidedRequests',
  'workRequest.decideFinal finalQueue',
  'workRequest.decideFinal leadRejectedLeadRequests',
  'workRequest.decideFinal ledRequests',
  'workRequest.decideFinal ownRequests',
  'workRequest.decideLead allRequests',
  'workRequest.decideLead decidedRequests',
  'workRequest.decideLead finalQueue',
  'workRequest.decideLead leadRejectedLeadRequests',
  'workRequest.decideLead ledRequests',
  'workRequest.decideLead ownRequests',
];

const pinnedHighRiskPermissions = [
  'account.provision',
  'account.reactivate',
  'account.read',
  'account.readPermissions',
  'account.suspend',
  'employee.adjustAttendance',
  'employee.adjustLeaveBalance',
  'employee.adjustLeaveRate',
  'employee.linkAccount',
  'employee.submitRequest',
  'employee.update',
  'team.assign',
  'workRequest.cancel',
  'workRequest.cancelApproved',
  'workRequest.decideFinal',
  'workRequest.decideLead',
];

const pinnedOtherPermissions = [
  'employee.read',
  'employee.readAttendance',
  'employee.readAttendanceAdjustment',
  'employee.readLeaveBalance',
  'employee.reportAttendance',
  'employee.reportBirthday',
  'employee.reportLateEarly',
  'employee.reportLeave',
  'employee.reportSeniority',
  'employee.reportWfh',
  'employeeIdentity.read',
  'employeeIdentity.update',
  'hrCompany.approvals',
  'hrCompany.createEmployee',
  'hrCompany.createTeam',
  'hrCompany.managePeriod',
  'hrCompany.read',
  'leaveRate.read',
  'role.read',
  'setting.read',
  'setting.readProfile',
  'setting.updateProfile',
  'setting.updateRule',
  'team.approvals',
  'team.read',
  'team.update',
  'workCalendar.manage',
  'workCalendar.read',
  'workRequest.read',
  'workRequest.readDecided',
  'workRequest.readLeadRejected',
];

test('the high-risk pairs are exactly the pinned list and all are selectable pairs of the release', () => {
  const actual = highRiskGrantPairs.map((p) => `${p.permission} ${p.template}`).sort();
  assert.deepEqual(actual, pinnedHighRiskPairs);
  assert.equal(new Set(actual).size, actual.length);
  for (const pair of actual) assert.ok(selectable.includes(pair), pair);
});

test('every permission of the release is classified: a new permission fails this test until decided', () => {
  assert.equal(selectable.length, 125);
  const permissions = [...new Set(selectable.map((pair) => pair.split(' ')[0]!))].sort();
  assert.deepEqual([...pinnedHighRiskPermissions, ...pinnedOtherPermissions].sort(), permissions);
  const risky = new Set(highRiskGrantPairs.map((p) => p.permission));
  assert.deepEqual([...risky].sort(), pinnedHighRiskPermissions);
});

test('selfApproval needs both permissions of the pair in one role, whatever their templates', () => {
  assert.deepEqual([...SELF_APPROVAL_PERMISSIONS].sort(), [
    'hrCompany.approvals',
    'workRequest.decideFinal',
  ]);
  assert.equal(
    hasSelfApproval([grant('hrCompany.approvals', 'company'), grant('workRequest.decideFinal')]),
    true,
  );
  assert.equal(hasSelfApproval([grant('hrCompany.approvals', 'company')]), false);
  assert.equal(hasSelfApproval([grant('workRequest.decideFinal', 'allRequests')]), false);
  assert.equal(hasSelfApproval([]), false);
});
